#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using i128 = __int128_t;
using vi = vector<ll>;
using vvi = vector<vi>;

ll mulMod(ll a, ll b, ll mod) {
    return static_cast<ll>((static_cast<i128>(a) * b) % mod);
}

ll BinModExp(ll base, ll exp, ll mod) {
    ll ans = 1 % mod;
    ll temp = base % mod;

    while (exp > 0) {
        if (exp & 1LL) ans = mulMod(ans, temp, mod);
        temp = mulMod(temp, temp, mod);
        exp >>= 1LL;
    }
    return ans;
}

vvi Multiply_Matrix(const vvi& A, const vvi& B, ll mod) {
    vvi C(A.size(), vi(B[0].size(), 0));

    for (size_t i = 0; i < A.size(); ++i) {
        for (size_t k = 0; k < B.size(); ++k) {
            for (size_t j = 0; j < B[0].size(); ++j) {
                C[i][j] = static_cast<ll>(
                    (static_cast<i128>(C[i][j]) +
                     static_cast<i128>(A[i][k]) * B[k][j]) % mod
                );
            }
        }
    }
    return C;
}

vvi Expon_Matrix(vvi A, ll exp, ll mod) {
    vvi result(A.size(), vi(A.size(), 0));
    for (size_t i = 0; i < A.size(); ++i) {
        result[i][i] = 1 % mod;
    }

    while (exp > 0) {
        if (exp & 1LL) result = Multiply_Matrix(result, A, mod);
        A = Multiply_Matrix(A, A, mod);
        exp >>= 1LL;
    }
    return result;
}

ll Nfibo(ll n, ll mod) {
    vvi A = {{1, 1}, {1, 0}};
    A = Expon_Matrix(A, n, mod);
    return (A[0][0] + A[0][1]) % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k, l, m;

    while (cin >> n >> k >> l >> m) {
        bool tooLarge = false;

        if (k > 0) {
            if (l < 0) {
                tooLarge = true;
            } else if (l < 63) {
                tooLarge = (1LL << l) < k;
            }
        }

        if (tooLarge) {
            cout << 0 << '\n';
            continue;
        }

        ll A = BinModExp(2, n, m);
        ll B = Nfibo(n, m);
        ll ans = 1 % m;

        for (ll i = 0; i < l; ++i) {
            bool bitSet = i < 63 && ((static_cast<unsigned long long>(k) >> i) & 1ULL);
            ll factor = bitSet ? (A - B + m) % m : B;
            ans = mulMod(ans, factor, m);
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using Matrix = vector<vector<ll>>;

ll modMultiply(ll a, ll b, ll mod) {
    return static_cast<ll>((__int128)a * b % mod);
}

ll binModExp(ll base, ll exp, ll mod) {
    ll result = 1 % mod;
    base %= mod;

    while (exp > 0) {
        if (exp & 1LL) result = modMultiply(result, base, mod);
        base = modMultiply(base, base, mod);
        exp >>= 1;
    }
    return result;
}

Matrix multiplyMatrix(const Matrix& a, const Matrix& b, ll mod) {
    Matrix c(a.size(), vector<ll>(b[0].size(), 0));

    for (size_t i = 0; i < a.size(); ++i) {
        for (size_t k = 0; k < b.size(); ++k) {
            for (size_t j = 0; j < b[0].size(); ++j) {
                c[i][j] = (c[i][j] + modMultiply(a[i][k], b[k][j], mod)) % mod;
            }
        }
    }
    return c;
}

Matrix exponentiateMatrix(Matrix base, ll exp, ll mod) {
    Matrix result(base.size(), vector<ll>(base.size(), 0));
    for (size_t i = 0; i < base.size(); ++i) {
        result[i][i] = 1 % mod;
    }

    while (exp > 0) {
        if (exp & 1LL) result = multiplyMatrix(result, base, mod);
        base = multiplyMatrix(base, base, mod);
        exp >>= 1;
    }
    return result;
}

ll nFibo(ll n, ll mod) {
    Matrix a = {{1 % mod, 1 % mod}, {1 % mod, 0}};
    a = exponentiateMatrix(a, n, mod);
    return (a[0][0] + a[0][1]) % mod;
}

