    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k, l, m;
    while (cin >> n >> k >> l >> m) {
        bool tooLarge = false;
        if (k > 0 && l < 63) {
            tooLarge = (static_cast<unsigned long long>(k) > (1ULL << l));
        }

        if (tooLarge) {
            cout << 0 << '\n';
            continue;
        }

        ll a = binModExp(2, n, m);
        ll b = nFibo(n, m);
        ll ans = 1 % m;
        ll oneBitFactor = static_cast<ll>(((__int128)a - b + m) % m);

        for (ll i = 0; i < l; ++i) {
            bool bitSet = i < 63 && ((static_cast<unsigned long long>(k) >> i) & 1ULL);
            ans = modMultiply(ans, bitSet ? oneBitFactor : b, m);
        }

        cout << ans << '\n';
    }

    return 0;
}

