bool PowerOfTwoLessThan(ll l, ll k) {
    if (k <= 0) return false;
    if (l >= 63) return false;
    return (1LL << l) < k;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k, l, m;
    while (cin >> n >> k >> l >> m) {
        if (PowerOfTwoLessThan(l, k)) {
            cout << 0 << '\n';
            continue;
        }

        ll A = BinModExp(2, n, m);
        ll B = Nfibo(n, m);
        ll ans = 1 % m;
        ll used = min<ll>(l, 63);

        for (ll i = 0; i < used; ++i) {
            if ((static_cast<unsigned long long>(k) >> i) & 1ULL) {
                ll factor = (A - B) % m;
                if (factor < 0) factor += m;
                ans = MulMod(ans, factor, m);
            } else {
                ans = MulMod(ans, B, m);
            }
        }

        if (l > used) {
            ans = MulMod(ans, BinModExp(B, l - used, m), m);
        }

        cout << ans << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;
using ull = unsigned long long;

ll mulMod(ll a, ll b, ll mod) {
    return static_cast<ll>((i128)a * b % mod);
}

ll binModExp(ll base, ll exp, ll mod) {
    ll result = 1 % mod;
    base %= mod;
    if (base < 0) base += mod;

    while (exp > 0) {
        if (exp & 1) result = mulMod(result, base, mod);
        base = mulMod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

struct Matrix {
    ll a[2][2]{};
};

Matrix multiply(const Matrix& x, const Matrix& y, ll mod) {
    Matrix result;
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            i128 value = 0;
            for (int k = 0; k < 2; ++k)
                value += (i128)x.a[i][k] * y.a[k][j];
            result.a[i][j] = static_cast<ll>(value % mod);
        }
    }
    return result;
}

Matrix matrixPower(Matrix base, ll exp, ll mod) {
    Matrix result;
    result.a[0][0] = result.a[1][1] = 1 % mod;

    while (exp > 0) {
        if (exp & 1) result = multiply(result, base, mod);
        base = multiply(base, base, mod);
        exp >>= 1;
    }
    return result;
}

ll nFibo(ll n, ll mod) {
    Matrix base;
    base.a[0][0] = base.a[0][1] = base.a[1][0] = 1 % mod;

    Matrix result = matrixPower(base, n, mod);
    return static_cast<ll>(((i128)result.a[0][0] + result.a[0][1]) % mod);
}

bool twoPowerLessThanK(ll l, ll k) {
    if (k <= 0) return false;
    if (l < 0) return true;
    if (l >= 63) return false;
    return (1LL << l) < k;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k, l, m;
    while (cin >> n >> k >> l >> m) {
        if (twoPowerLessThanK(l, k)) {
            cout << 0 << '\n';
            continue;
        }

        ll a = binModExp(2, n, m);
        ll b = nFibo(n, m);
        ll setBits;

        if (l <= 0) {
            setBits = 0;
        } else if (l >= 64) {
            setBits = __builtin_popcountll(static_cast<ull>(k));
        } else {
            ull mask = (1ULL << l) - 1;
            setBits = __builtin_popcountll(static_cast<ull>(k) & mask);
        }

        ll first = (a - b) % m;
        if (first < 0) first += m;

        ll answer = mulMod(
            binModExp(first, setBits, m),
            binModExp(b, l - setBits, m),
            m
        );

        cout << answer << '\n';
    }

    return 0;
}

